/**
 * mfm-wargear-crosscheck.ts — cross-check the BSData-derived wargear-options
 * (convert-bsdata-wargear.ts) against the GW Munitorum Field Manual dump.
 *
 * The dump's `replaces`/count semantics live in prose, but the SET of optional
 * wargear items per datasheet is structural: `wargear_option` rows (the selectable
 * choices, each with points) join to a `wargear_option_group` carrying the
 * `datasheetId`, and each option references a `wargear_item` with an English name.
 * We compare, per unit, that GW set against the set of weapon/wargear ids the
 * BSData extractor put into `replaces`/`replacement`/`replacement_choice`.
 *
 * This is a one-time triage signal, NOT a CI gate (dump.json is gitignored — CI
 * can't see it). Divergences are name-drift between sources OR genuine
 * disagreements (e.g. a swap BSData and GW direct differently) worth a human look.
 *
 * Usage:
 *   npx tsx tools/src/mfm-wargear-crosscheck.ts [--dump <path>]
 *   (writes data/core/_reports/mfm-wargear-crosscheck.md)
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { fileURLToPath } from "node:url";
import { nameToId } from "./converters/id-generator.js";
import { DEFAULT_DUMP_PATH, loadDump } from "./mfm/loader.js";
import { CORE_DIR, readJsonArray } from "./mfm/repo-files.js";
import { repoDirForFactionName } from "./mfm/faction-map.js";

const REPORT = join(CORE_DIR, "_reports", "mfm-wargear-crosscheck.md");

interface WargearOption {
  unit_id: string;
  replaces?: string[];
  replacement?: string[];
  replacement_choice?: string[][];
}


function safeId(name: string | undefined): string | null {
  if (!name) return null;
  try {
    return nameToId(name);
  } catch {
    return null;
  }
}
function repoDirs(): string[] {
  return readdirSync(CORE_DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith("_"))
    .map((d) => d.name)
    .sort();
}

function dumpArg(): string {
  const i = process.argv.indexOf("--dump");
  return i !== -1 ? process.argv[i + 1] : DEFAULT_DUMP_PATH;
}

function main(): void {
  const dump = loadDump(dumpArg());

  // datasheetId → set of optional wargear-item ids (from the choice tables).
  const optionItemsByDatasheet = new Map<string, Set<string>>();
  const optionsByGroup = dump.groupBy("wargear_option", "wargearOptionGroupId");
  const wargearItem = dump.byId("wargear_item");
  for (const group of dump.table("wargear_option_group")) {
    const dsId = group.datasheetId;
    if (!dsId) continue;
    const set = optionItemsByDatasheet.get(dsId) ?? optionItemsByDatasheet.set(dsId, new Set()).get(dsId)!;
    for (const opt of optionsByGroup.get(String(group.id)) ?? []) {
      const id = safeId(dump.enName(wargearItem.get(opt.wargearItemId)));
      if (id) set.add(id);
    }
  }

  // Build, per faction, unit_id → GW dump option-item set (live datasheets only).
  const dumpByFaction = new Map<string, Map<string, Set<string>>>();
  for (const ds of dump.table("datasheet")) {
    if (ds.isLegends || !ds.id) continue;
    const items = optionItemsByDatasheet.get(ds.id);
    if (!items || items.size === 0) continue;
    const fkId = dump.factionKeywordOfDatasheet(ds.id);
    const fkName = dump.enName(dump.byId("faction_keyword").get(fkId ?? ""));
    const faction = repoDirForFactionName(fkName);
    const unitId = safeId(dump.enName(ds));
    if (!faction || !unitId) continue;
    const m = dumpByFaction.get(faction) ?? dumpByFaction.set(faction, new Map()).get(faction)!;
    (m.get(unitId) ?? m.set(unitId, new Set()).get(unitId)!).forEach(() => {});
    const set = m.get(unitId)!;
    for (const id of items) set.add(id);
  }

  // Item-level names drift between the two sources (and the dump lists base+default
  // items, not just swap deltas), so an exact item diff is noise. The reliable,
  // actionable signal is STRUCTURAL: do both sources agree a unit has wargear
  // options at all, and — where both list options — do their weapon-id sets overlap?
  let both = 0; // both sources give the unit options
  let bsOnly = 0; // BSData extracted options, GW dump lists none — possible over-extraction
  let gwOnly = 0; // GW lists options, BSData extracted none — a miss (see triage report)
  let bothNoOverlap = 0; // both list options but share NO weapon id — genuine disagreement
  const bsOnlyList: string[] = [];
  const noOverlapList: string[] = [];

  for (const faction of repoDirs()) {
    const bsOpts = readJsonArray<WargearOption>(join(CORE_DIR, faction, "wargear-options.json"));
    const dumpUnits = dumpByFaction.get(faction) ?? new Map<string, Set<string>>();
    if (bsOpts.length === 0 && dumpUnits.size === 0) continue;
    const bsByUnit = new Map<string, Set<string>>();
    for (const o of bsOpts) {
      const set = bsByUnit.get(o.unit_id) ?? bsByUnit.set(o.unit_id, new Set()).get(o.unit_id)!;
      for (const w of [...(o.replaces ?? []), ...(o.replacement ?? []), ...(o.replacement_choice ?? []).flat()]) {
        set.add(w);
      }
    }
    for (const unit of new Set<string>([...bsByUnit.keys(), ...dumpUnits.keys()])) {
      const bs = bsByUnit.get(unit);
      const gw = dumpUnits.get(unit);
      if (bs && gw) {
        both++;
        if (![...bs].some((x) => gw.has(x))) {
          bothNoOverlap++;
          noOverlapList.push(`${faction}/${unit}`);
        }
      } else if (bs) {
        bsOnly++;
        bsOnlyList.push(`${faction}/${unit}`);
      } else {
        gwOnly++;
      }
    }
  }

  const lines = [
    "# BSData ↔ GW MFM dump wargear cross-check",
    "",
    "Structural agreement on which units carry wargear options. Item-level names",
    "drift between sources (and the dump lists base/default items, not swap deltas),",
    "so this checks unit-level presence + whether option weapon-id sets overlap.",
    "",
    `- **Both sources list options:** ${both}`,
    `  - of which share ≥1 weapon id: ${both - bothNoOverlap}`,
    `  - of which share NO weapon id (genuine disagreement — investigate): ${bothNoOverlap}`,
    `- **BSData-only (GW dump lists none — check for over-extraction):** ${bsOnly}`,
    `- **GW-dump-only (BSData missed — see triage reports):** ${gwOnly}`,
    "",
    "## BSData-only units (BSData extracted options, GW dump has none)",
    "",
    "_NB: Space Marine chapter units (Crusader Squad, Deathwing, Kill Teams, …)_",
    "_appear here because the dump keys them to per-chapter faction keywords that_",
    "_don't consolidate to `adeptus-astartes` — a dump-side mapping artifact, not_",
    "_over-extraction. The unit genuinely has the options BSData found._",
    "",
    ...bsOnlyList.map((u) => `- ${u}`),
    "",
    "## Both list options but share no weapon id (investigate)",
    "",
    ...noOverlapList.map((u) => `- ${u}`),
    "",
  ];
  writeFileSync(REPORT, lines.join("\n") + "\n");
  console.log(
    `both=${both} (overlap=${both - bothNoOverlap}, no-overlap=${bothNoOverlap}) bsOnly=${bsOnly} gwOnly=${gwOnly} → ${REPORT}`,
  );
}

main();
